        s=s.replace('          # All twelve exact named passes are required on this head and invocation.\n          for evidence in \\\n            "KeyFlowsQATests testQA1_AddFromURL_JSONLD]\' passed" \\\n            "KeyFlowsQATests testQA1_AddFromURL_InstagramCaption]\' passed" \\\n            "KeyFlowsQATests testQA1_AddFromURL_HiddenCaptionFallback]\' passed" \\\n            "KeyFlowsQATests testQA2_AddFromPhoto]\' passed" \\\n            "KeyFlowsQATests testQA3_GenerateAndEdit]\' passed" \\\n            "KeyFlowsQATests testQA4_Save]\' passed" \\\n            "KeyFlowsQATests testQA5_Share]\' passed" \\\n            "KeyFlowsQATests testQA6_OpenShared]\' passed" \\\n            "KeyFlowsQATests testQA8_Timers]\' passed" \\\n            "AteUITests test28_GroupSortAndMenus]\' passed" \\\n            "AteUITests test29_ReorderMyOrder]\' passed" \\\n            "AteUITests test29b_ReorderMyOrderActions]\' passed"; do\n            grep -qF "$evidence" dogfood-critical-flows.log || { echo "::error::missing required named pass: $evidence"; exit 1; }\n          done\n          grep -E "Test Case .* (passed|failed)|Executed|TEST SUCCEEDED" dogfood-critical-flows.log | tail -50','          grep -E "Test Case .* (passed|failed)|Executed|TEST SUCCEEDED" dogfood-critical-flows.log | tail -50')
        self.assertEqual(s.count('          python3 -c \'import time; print("critical-start monotonic_ns=" + str(time.monotonic_ns()))\' > build/dogfood-critical-timing.txt\n          record_critical_end() {\n            python3 -c \'import time; print("critical-end monotonic_ns=" + str(time.monotonic_ns()))\' >> build/dogfood-critical-timing.txt\n          }\n          trap record_critical_end EXIT\n          # QA1 flow = the exact three cases below;'),1)
        s=s.replace('          python3 -c \'import time; print("critical-start monotonic_ns=" + str(time.monotonic_ns()))\' > build/dogfood-critical-timing.txt\n          record_critical_end() {\n            python3 -c \'import time; print("critical-end monotonic_ns=" + str(time.monotonic_ns()))\' >> build/dogfood-critical-timing.txt\n          }\n          trap record_critical_end EXIT\n          # QA1 flow = the exact three cases below;','          # QA1 flow = the exact three cases below;')
        self.assertEqual(s.count("        id: critical_flows\n        if: ${{ success() && steps.build_tests.outcome == 'success' }}\n"),1)
